Lemma w4s_le64pc3 : forall (RNG : footprint) (Q : machine_state -> Prop) (mm : amem) (SS K r P : Z) (src : list Z) (w216 : word)
    (ra gp tp x5 x6 x7 x8 x9 a0 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  bytes_at asegs mm SS (map (Z_to_bv 8) src) -> 0 <= K -> K + 8 <= zlen src -> zlen src < 2^26 -> 16 <= SS ->
  SS + zlen src <= 2^47 -> rng RNG SS (zlen src) ->
  rw_cells asegs mm (P + 216) [C8 w216] -> mem_inv asegs mm -> rng RNG P 496 -> rng_aimg RNG ->
  0x10007fff8000 <= P -> P + 496 <= 2^47 -> 1 <= r <= 255 ->
  (forall mm' (cw x5' a0' a2' a4' a5' a6' a7' : word),
     munch [(P + 216, P + 224)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> rw_cells asegs mm' (P + 216) [C8 cw] ->
     evtF asegs RNG Q (MS (mkR ra (Z_to_bv 64 P) gp tp x5' x6 x7 x8 x9 a0' a1 a2' a3 a4' a5' a6' a7' s2
                              (Z_to_bv 64 (8 - Z.log2 r)) s4 s5 s6 s7 (Z_to_bv 64 (SS + K)) s9 s10 s11 t3 t4 t5 t6)
                         F (Z_to_bv 64 0x90c0c) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR ra (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 a0 a1 (Z_to_bv 64 r) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7
                           (Z_to_bv 64 (SS + K)) s9 s10 s11 t3 t4 t5 t6)
                       F (Z_to_bv 64 0x9091c) fc None mm (seg_rom asegs)).
